INSERT INTO `tb_materi` VALUES (1,'Semester 1',1,1,'Expression of Greeting & Parting','Mempelajari ungkapan menyapa (greeting) saat bertemu seseorang dan ungkapan berpamitan (parting) secara formal maupun informal.','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Expressions of Greeting and Parting (Leave-Taking)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Mengidentifikasi fungsi sosial, struktur teks, dan unsur kebahasaan dari ungkapan menyapa (<i>greeting</i>) dan berpamitan (<i>parting/leave-taking</i>).</li>\r\n  <li>Membedakan penggunaan ragam formal (resmi/sopan) dan informal (santai/akrab) berdasarkan lawan bicara dan situasi.</li>\r\n  <li>Menyusun kalimat serta merespons sapaan dan pamitan dengan tata bahasa, intonasi, dan pelafalan yang tepat.</li>\r\n  <li>Mempraktikkan percakapan transaksional dan interpersonal pendek secara lisan maupun tertulis dalam konteks kehidupan sehari-hari.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. Definition of Greeting:</b><br>\r\n<i>Greeting</i> adalah ungkapan yang diucapkan untuk menyapa seseorang ketika baru bertemu atau memulai interaksi. Menyapa bertujuan untuk menunjukkan kesopanan, keramahan, serta membuka saluran komunikasi yang baik.</p>\r\n\r\n<p><b>B. Definition of Parting (Leave-Taking):</b><br>\r\n<i>Parting</i> atau <i>leave-taking</i> adalah ungkapan yang digunakan ketika seseorang hendak mengakhiri percakapan atau berpisah dari lawan bicara. Ungkapan ini bertujuan menutup pembicaraan dengan sopan dan memberi kesan menyenangkan.</p>\r\n\r\n<h3>3. Rumus & Pola Kalimat (Formula & Structures)</h3>\r\n<p>Untuk membentuk interaksi yang natural, gunakan rumus dasar struktur percakapan berikut:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Jenis Pola</th>\r\n    <th>Rumus / Formula</th>\r\n    <th>Contoh Penerapan</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Sapaan Bertingkat</b></td>\r\n    <td><i>[Salutation/Greeting] + [Name/Title] + [Asking Condition]?</i></td>\r\n    <td>\"Good morning, Mr. Hadi. How are you doing?\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Respons Sapaan</b></td>\r\n    <td><i>[Greeting Response] + [Condition Response] + [Gratitude] + [Return Question]?</i></td>\r\n    <td>\"Good morning! I am very well, thank you. And you?\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Berpamitan (Parting)</b></td>\r\n    <td><i>[Pre-closing Reason] + [Leave-taking Expression] + [Wishes/Follow-up]</i></td>\r\n    <td>\"I have to go now. Goodbye, see you tomorrow!\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Respons Pamitan</b></td>\r\n    <td><i>[Parting Response] + [Care/Safety Expression]</i></td>\r\n    <td>\"Goodbye! Take care on your way home.\"</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Penjelasan Mendalam & Pembagian Waktu (In-Depth Explanation)</h3>\r\n\r\n<p><b>A. Formal vs. Informal Context:</b></p>\r\n<ul>\r\n  <li><b>Formal:</b> Digunakan kepada orang yang lebih tua, guru, kepala sekolah, orang asing, atau dalam suasana formal (upacara, kelas, rapat). Mengutamakan rasa hormat dan kesantunan.</li>\r\n  <li><b>Informal:</b> Digunakan kepada teman sebaya, sahabat dekat, anggota keluarga, atau dalam suasana santai (waktu istirahat, bermain, nongkrong).</li>\r\n</ul>\r\n\r\n<p><b>B. Aturan Penunjuk Waktu Sapaan Formal Bahasa Inggris:</b></p>\r\n<ul>\r\n  <li><b>Good morning:</b> Digunakan sejak pukul 00.01 tengah malam hingga pukul 11.59 siang.</li>\r\n  <li><b>Good afternoon:</b> Digunakan sejak pukul 12.00 siang hingga matahari terbenam (sekitar pukul 17.59 / 18.00 sore).</li>\r\n  <li><b>Good evening:</b> Digunakan saat bertemu orang lain pada malam hari (mulai pukul 18.00 sampai larut malam). <i>Catatan:</i> \"Good evening\" adalah sapaan bertemu, bukan pamitan!</li>\r\n  <li><b>Good night:</b> <u>Bukan</u> sapaan bertemu! \"Good night\" hanya diucapkan sebagai ungkapan pamitan (parting) saat hendak berpisah di malam hari atau ketika hendak pergi tidur.</li>\r\n</ul>\r\n\r\n<h3>5. Daftar Ungkapan Lengkap (Expressions & Responses)</h3>\r\n\r\n<p><b>A. Expressions of Greeting:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori</th>\r\n    <th>Expression (Ungkapan)</th>\r\n    <th>Meaning (Arti)</th>\r\n    <th>Responses (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"4\"><b>Formal</b></td>\r\n    <td>Good morning / afternoon / evening</td>\r\n    <td>Selamat pagi / siang-sore / malam</td>\r\n    <td>Good morning / afternoon / evening</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How do you do? <i>(Khusus pertemuan pertama)</i></td>\r\n    <td>Apa kabar? / Salam kenal</td>\r\n    <td>How do you do?</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How are you?</td>\r\n    <td>Bagaimana kabar Anda?</td>\r\n    <td>I am fine / I am very well, thank you.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>It is a pleasure to meet you.</td>\r\n    <td>Senang bertemu dengan Anda.</td>\r\n    <td>Pleasure to meet you too.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"5\"><b>Informal</b></td>\r\n    <td>Hi! / Hello!</td>\r\n    <td>Hai! / Halo!</td>\r\n    <td>Hello! / Hi!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How are you doing?</td>\r\n    <td>Bagaimana kabarmu?</td>\r\n    <td>I\'m great! / Not bad!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>How\'s life? / How are things?</td>\r\n    <td>Gimana kabarnya?</td>\r\n    <td>Pretty good / Everything is fine.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>What\'s up?</td>\r\n    <td>Ada apa? / Apa kabar?</td>\r\n    <td>Nothing much / Just chilling.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Nice to meet you!</td>\r\n    <td>Senang bertemu denganmu!</td>\r\n    <td>Nice to meet you too!</td>\r\n  </tr>\r\n</table>\r\n\r\n<p><b>B. Expressions of Parting / Leave-Taking:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori</th>\r\n    <th>Expression (Ungkapan)</th>\r\n    <th>Meaning (Arti)</th>\r\n    <th>Responses (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\"><b>Formal</b></td>\r\n    <td>Goodbye, Sir/Ma\'am.</td>\r\n    <td>Selamat tinggal, Pak/Bu.</td>\r\n    <td>Goodbye, have a good day.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Good night.</td>\r\n    <td>Selamat tidur / Selamat malam (pisah).</td>\r\n    <td>Good night, have a nice dream.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>It was nice meeting you.</td>\r\n    <td>Senang bisa bertemu dengan Anda.</td>\r\n    <td>It was nice meeting you too.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"5\"><b>Informal</b></td>\r\n    <td>Bye! / Bye-bye!</td>\r\n    <td>Dah! / Sampai jumpa!</td>\r\n    <td>Bye! / See ya!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>See you later / See you soon!</td>\r\n    <td>Sampai jumpa nanti / segera!</td>\r\n    <td>See you!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>See you tomorrow!</td>\r\n    <td>Sampai jumpa besok!</td>\r\n    <td>See you tomorrow!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I must get going now.</td>\r\n    <td>Aku harus cabut/pergi sekarang.</td>\r\n    <td>Sure, catch you later!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Take care!</td>\r\n    <td>Hati-hati di jalan ya!</td>\r\n    <td>You too! / Thanks!</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>6. Contoh Percakapan (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Formal Setting (Antara Siswa dan Guru di Sekolah)</b><br>\r\n<i>Situasi: Dodi berpapasan dengan Ibu Ratna, guru Bahasa Inggris, di koridor perpustakaan sekolah pada pukul 07.15 pagi.</i></p>\r\n<p>\r\n<b>Dodi:</b> \"Good morning, Mrs. Ratna. How are you this morning?\"<br>\r\n<b>Mrs. Ratna:</b> \"Good morning, Dodi. I am doing very well, thank you. You look fresh today, how about you?\"<br>\r\n<b>Dodi:</b> \"I am wonderful, thank you Ma\'am. Are you going to the library?\"<br>\r\n<b>Mrs. Ratna:</b> \"Yes, I need to return some textbooks before the bell rings.\"<br>\r\n<b>Dodi:</b> \"Alright, Ma\'am. The bell is ringing, so I have to go to my class now. Goodbye, Mrs. Ratna!\"<br>\r\n<b>Mrs. Ratna:</b> \"Goodbye, Dodi. Have a great study today!\"<br>\r\n<b>Dodi:</b> \"Thank you, Ma\'am. See you later!\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Informal Setting (Antara Dua Orang Sahabat)</b><br>\r\n<i>Situasi: Rian dan Kevin bertemu di kantin sekolah saat jam istirahat siang.</i></p>\r\n<p>\r\n<b>Kevin:</b> \"Hey, Rian! What\'s up, bro?\"<br>\r\n<b>Rian:</b> \"Hi, Kev! Pretty good, just a bit tired after PE class. How are things with you?\"<br>\r\n<b>Kevin:</b> \"Never better! Look at my new football jersey. Do you want to play soccer at the field this afternoon?\"<br>\r\n<b>Rian:</b> \"That sounds awesome! Let\'s meet at 4 p.m.\"<br>\r\n<b>Kevin:</b> \"Deal. Oh, my sister is calling me, I\'ve got to run.\"<br>\r\n<b>Rian:</b> \"Okay, no problem. Catch you later, Kev!\"<br>\r\n<b>Kevin:</b> \"See ya later, Rian! Take care!\"\r\n</p>\r\n\r\n<p><b>Dialogue 3: Night Situation (Perpisahan Malam Hari)</b><br>\r\n<i>Situasi: Maya sedang belajar kelompok di rumah Nita hingga pukul 20.30 malam.</i></p>\r\n<p>\r\n<b>Maya:</b> \"Nita, our science project is finally done. It\'s almost 9 o\'clock, my father is waiting outside.\"<br>\r\n<b>Nita:</b> \"Thank you so much for your help today, Maya.\"<br>\r\n<b>Maya:</b> \"Don\'t mention it! Good night, Nita. See you tomorrow at school.\"<br>\r\n<b>Nita:</b> \"Good night, Maya. Take care on the road and have sweet dreams!\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Salah:</b> Mengucapkan <i>\"Good night!\"</i> saat baru bertemu teman di malam hari pada jam 19.00.<br>\r\n  <b>Benar:</b> Ucapkan <i>\"Good evening!\"</i> saat bertemu, lalu ucapkan <i>\"Good night!\"</i> hanya ketika hendak pulang atau tidur.</li>\r\n  <li><b>Salah:</b> Menjawab <i>\"How do you do?\"</i> dengan jawaban <i>\"I am fine, thank you.\"</i><br>\r\n  <b>Benar:</b> <i>\"How do you do?\"</i> adalah sapaan formal saat pertama kali berkenalan, sehingga respons yang baku dan tepat adalah kembali menjawab: <i>\"How do you do?\"</i></li>\r\n  <li><b>Salah:</b> Menulis pemisahan kata yang salah seperti <i>\"Good bye\"</i> menjadi satu huruf yang rancu, atau melupakan tanda seru/tanya pada ekspresi sapaan.</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Greeting:</b> Sapaan / Ucapan salam saat bertemu</li>\r\n  <li><b>Parting / Leave-taking:</b> Ungkapan berpamitan / Perpisahan</li>\r\n  <li><b>Response:</b> Respons / Tanggapan / Balasan</li>\r\n  <li><b>Salutation:</b> Salam pembuka</li>\r\n  <li><b>Pre-closing:</b> Ungkapan pendahulu sebelum mengakhiri obrolan (misal: <i>\"I have to go now\"</i>)</li>\r\n  <li><b>Polite / Courteous:</b> Sopan / Santun</li>\r\n  <li><b>Peers:</b> Teman sebaya</li>\r\n  <li><b>Take care:</b> Hati-hati / Jaga diri</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n<p><b>A. Lengkapi dialog rumpang di bawah ini:</b></p>\r\n<ol>\r\n  <li>Rani: \"Good afternoon, Mr. Joko.\"<br>\r\n      Mr. Joko: \"..., Rani. Where are you going?\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n  <li>Dimas: \"It is getting late. I have to go home now. Good night, Fajar!\"<br>\r\n      Fajar: \"..., Dimas. Sweet dreams!\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n  <li>Sarah: \"Hi, Tiara! How are you doing?\"<br>\r\n      Tiara: \"..., thanks. And you?\"<br>\r\n      <i>Jawaban: ____________________</i></li>\r\n</ol>\r\n\r\n<p><b>B. Pertanyaan Benar/Salah (True or False):</b></p>\r\n<ol>\r\n  <li>We say \"Good night\" to greet someone when we meet them at 7:00 PM. (<b>True / False</b>)</li>\r\n  <li>\"What\'s up?\" is an informal greeting used among friends. (<b>True / False</b>)</li>\r\n  <li>The correct response to \"How do you do?\" is \"How do you do?\". (<b>True / False</b>)</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(2,'Semester 1',1,2,'Expression of Thanking & Apologizing','Mempelajari cara berterima kasih (gratitude) atas bantuan seseorang dan meminta maaf (apology) saat melakukan kesalahan beserta responnya.','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Expressions of Thanking (Gratitude) and Apologizing (Apology)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari materi ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Memahami fungsi sosial, struktur teks, dan unsur kebahasaan ungkapan terima kasih (<i>thanking/gratitude</i>) dan meminta maaf (<i>apologizing</i>).</li>\r\n  <li>Menggunakan pola tata bahasa yang tepat, termasuk penggunaan preposisi <i>for</i> diikuti kata benda (<i>noun</i>) atau kata kerja bentuk <i>-ing</i> (<i>gerund</i>).</li>\r\n  <li>Membedakan ungkapan terima kasih dan permohonan maaf dalam situasi formal maupun santai (informal).</li>\r\n  <li>Menyusun serta memperagakan dialog interpersonal pendek yang melibatkan pemberian bantuan, penghargaan, kesalahan tanpa sengaja, dan respons yang sopan.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. Definition of Thanking (Expressing Gratitude):</b><br>\r\n<i>Thanking</i> adalah tindakan mengekspresikan rasa terima kasih atau penghargaan kepada orang lain atas bantuan, hadiah, kebaikan, pujian, maupun layanan yang telah diterima. Tujuannya adalah mempererat hubungan antarpribadi dan menunjukkan etika kesantunan.</p>\r\n\r\n<p><b>B. Definition of Apologizing (Expressing Apology):</b><br>\r\n<i>Apologizing</i> adalah tindakan mengakui kesalahan, kekeliruan, atau ketidaknyamanan yang ditimbulkan kepada orang lain serta menyampaikan penyesalan. Tujuannya adalah memulihkan hubungan baik, memperbaiki situasi, dan meredakan ketegangan antarindividu.</p>\r\n\r\n<h3>3. Rumus & Pola Tata Bahasa (Grammar & Sentence Patterns)</h3>\r\n<p>Dalam bahasa Inggris, ungkapan terima kasih dan maaf sering kali membutuhkan alasan di balik ucapan tersebut. Pola dasarnya menggunakan preposisi <b>\"for\"</b>:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori</th>\r\n    <th>Pola / Rumus (Formula)</th>\r\n    <th>Contoh Kalimat</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\"><b>Thanking (Berterima Kasih)</b></td>\r\n    <td><i>Thank you / Thanks + for + [Noun / Kata Benda]</i></td>\r\n    <td>\"Thank you for <b>the delicious lunch</b>.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><i>Thank you / Thanks + for + [Verb-ing / Gerund]</i></td>\r\n    <td>\"Thanks for <b>helping</b> me with the homework.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"2\"><b>Apologizing (Meminta Maaf)</b></td>\r\n    <td><i>I am sorry + for + [Noun / Kata Benda]</i></td>\r\n    <td>\"I am sorry for <b>the mess</b> in the room.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><i>I am sorry + for + [Verb-ing / Gerund]</i></td>\r\n    <td>\"I am sorry for <b>coming</b> late to school.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Pola Permohonan Maaf Formal</b></td>\r\n    <td><i>I apologize for + [Noun / Verb-ing]</i></td>\r\n    <td>\"I apologize for <b>losing</b> your English dictionary.\"</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Penjelasan Mendalam (In-Depth Explanation)</h3>\r\n\r\n<p><b>A. Nuansa dan Tingkatan Rasa Terima Kasih:</b></p>\r\n<ul>\r\n  <li><b>Tingkat Biasa/Sehari-hari:</b> Menggunakan <i>\"Thanks\"</i> atau <i>\"Thank you\"</i> untuk hal-hal kecil, seperti dipinjamkan penghapus atau diberi tahu nomor halaman buku.</li>\r\n  <li><b>Tingkat Mendalam/Sangat Bersyukur:</b> Menggunakan <i>\"Thank you very much\"</i>, <i>\"Thanks a million\"</i>, atau <i>\"I really appreciate it\"</i> saat seseorang memberikan bantuan besar, menyelamatkan situasi sulit, atau memberikan hadiah yang berharga.</li>\r\n</ul>\r\n\r\n<p><b>B. Perbedaan Mendasar Antara \"Excuse Me\" dan \"I\'m Sorry\":</b></p>\r\n<ul>\r\n  <li><b>Excuse me (Permisi):</b> Diucapkan <u>sebelum</u> melakukan sesuatu yang berpotensi mengganggu, menyela pembicaraan, melewati kerumunan orang, atau menarik perhatian orang lain (misal: <i>\"Excuse me, do you know where the library is?\"</i>).</li>\r\n  <li><b>I\'m sorry (Maaf):</b> Diucapkan <u>setelah</u> suatu kesalahan, insiden, atau ketidaknyamanan terjadi (misal: menumpahkan air, terlambat datang, atau mematahkan pensil teman).</li>\r\n</ul>\r\n\r\n<h3>5. Tabel Ungkapan Lengkap (Expressions & Responses)</h3>\r\n\r\n<p><b>A. Expressions of Thanking & Responses:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Tingkat Formalitas</th>\r\n    <th>Expressions of Gratitude</th>\r\n    <th>Arti</th>\r\n    <th>Accepting Thanks (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\"><b>Formal</b></td>\r\n    <td>Thank you very much, Sir/Ma\'am.</td>\r\n    <td>Terima kasih banyak, Pak/Bu.</td>\r\n    <td>You are very welcome.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I am very grateful for your assistance.</td>\r\n    <td>Saya sangat bersyukur atas bantuan Anda.</td>\r\n    <td>It is my pleasure. / Don\'t mention it.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I sincerely appreciate your help.</td>\r\n    <td>Saya sungguh menghargai bantuan Anda.</td>\r\n    <td>I am glad I could help.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"4\"><b>Informal</b></td>\r\n    <td>Thanks a lot! / Thanks a bunch!</td>\r\n    <td>Makasih banyak!</td>\r\n    <td>No problem! / Any time!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Thanks for lending me your pen.</td>\r\n    <td>Makasih udah minjemin pulpen.</td>\r\n    <td>Sure! / Don\'t worry about it.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>You are a lifesaver!</td>\r\n    <td>Kamu penolong banget!</td>\r\n    <td>Forget it! / Glad to help!</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Thanks, mate!</td>\r\n    <td>Makasih, kawan!</td>\r\n    <td>No sweat! / You bet!</td>\r\n  </tr>\r\n</table>\r\n\r\n<p><b>B. Expressions of Apologizing & Responses:</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Tingkat Formalitas</th>\r\n    <th>Expressions of Apology</th>\r\n    <th>Arti</th>\r\n    <th>Accepting Apologies (Tanggapan)</th>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"3\"><b>Formal</b></td>\r\n    <td>I do apologize for my mistake.</td>\r\n    <td>Saya sungguh memohon maaf atas kesalahan saya.</td>\r\n    <td>That is quite alright.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Please forgive me for being late.</td>\r\n    <td>Mohon maafkan saya karena terlambat.</td>\r\n    <td>Please do not worry about it.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I am terribly sorry for the inconvenience.</td>\r\n    <td>Saya sangat menyesal atas ketidaknyamanan ini.</td>\r\n    <td>It\'s fine, just don\'t do it again.</td>\r\n  </tr>\r\n  <tr>\r\n    <td rowspan=\"4\"><b>Informal</b></td>\r\n    <td>I\'m sorry. / So sorry!</td>\r\n    <td>Maaf ya.</td>\r\n    <td>Never mind. / It\'s okay.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Sorry for breaking your ruler.</td>\r\n    <td>Maaf ya udah matahin penggarismu.</td>\r\n    <td>It doesn\'t matter. I have another one.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>My bad! I didn\'t see your bag.</td>\r\n    <td>Salahku! Aku nggak sengaja liat tasmu.</td>\r\n    <td>No worries! / It\'s all good.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>I didn\'t mean to hurt your feelings.</td>\r\n    <td>Aku nggak berniat menyakiti perasaanmu.</td>\r\n    <td>That\'s fine, I understand.</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>6. Contoh Percakapan Interaktif (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Formal Interaction (Siswa Mengembalikan Buku ke Guru)</b><br>\r\n<i>Situasi: Bayu mengembalikan buku catatan materi Bahasa Inggris ke meja Pak Danang.</i></p>\r\n<p>\r\n<b>Bayu:</b> \"Excuse me, Mr. Danang. May I disturb you for a second?\"<br>\r\n<b>Mr. Danang:</b> \"Yes, Bayu. What can I do for you?\"<br>\r\n<b>Bayu:</b> \"Here is your grammar notebook, Sir. I have copied the summary. Thank you very much for lending it to me. It really helped me study.\"<br>\r\n<b>Mr. Danang:</b> \"You are very welcome, Bayu. I\'m pleased that it was useful for your preparation.\"<br>\r\n<b>Bayu:</b> \"Thank you again, Sir. Have a pleasant afternoon.\"<br>\r\n<b>Mr. Danang:</b> \"You too, Bayu. Keep up the good work!\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Informal Interaction (Permintaan Maaf Antarteman Sebaya)</b><br>\r\n<i>Situasi: Sandi tidak sengaja menumpahkan sedikit saus sambal ke jaket milik Farhan di kantin sekolah.</i></p>\r\n<p>\r\n<b>Sandi:</b> \"Oh no! Farhan, I am so sorry! I tripped over the chair leg and spilled sauce on your jacket.\"<br>\r\n<b>Farhan:</b> \"Ouch! Let me check... Ah, it\'s just on the outer sleeve.\"<br>\r\n<b>Sandi:</b> \"I am really sorry for being careless. Let me take it to the washbasin and clean it with some wet tissue, or I can wash it at home tonight.\"<br>\r\n<b>Farhan:</b> \"Don\'t worry about it, Sandi. It\'s an accident. The sauce can be washed away easily with water. No big deal!\"<br>\r\n<b>Sandi:</b> \"Phew, thanks for understanding, Farhan. I will be more careful next time.\"<br>\r\n<b>Farhan:</b> \"Never mind, bro! Let\'s just finish our meal.\"\r\n</p>\r\n\r\n<p><b>Dialogue 3: Combination of Apology and Gratitude (Keluarga/Rumah)</b><br>\r\n<i>Situasi: Alika lupa mematikan keran air di kamar mandi hingga ember meluap, lalu ditegur oleh sang ibu.</i></p>\r\n<p>\r\n<b>Mother:</b> \"Alika, did you fill the bathtub earlier? The water has overflowed onto the bathroom floor.\"<br>\r\n<b>Alika:</b> \"Oh dear, I totally forgot! I am terribly sorry for being so forgetful, Mom. I was rushing to do my homework.\"<br>\r\n<b>Mother:</b> \"It\'s alright, dear, but we must save water. Please take the mop and wipe the floor so nobody slips.\"<br>\r\n<b>Alika:</b> \"Right away, Mom. I\'ve mopped it clean now.\"<br>\r\n<b>Mother:</b> \"Good girl. Thank you for cleaning it up quickly.\"<br>\r\n<b>Alika:</b> \"You\'re welcome, Mom. I promise I won\'t forget next time.\"\r\n</p>\r\n\r\n<h3>7. Catatan Tata Bahasa & Kesalahan Umum (Grammar Notes & Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Kesalahan Preposisi dan Kata Kerja:</b><br>\r\n  <i>Salah:</i> \"Thank you for <u>help</u> me.\" atau \"Sorry for <u>come</u> late.\"<br>\r\n  <i>Benar:</i> \"Thank you for <b>helping</b> me.\" dan \"Sorry for <b>coming</b> late.\" (Setelah kata <i>for</i>, kata kerja wajib berubah menjadi bentuk <i>-ing</i> / gerund).</li>\r\n  <li><b>Kesalahan Penggunaan \"Please\":</b><br>\r\n  <i>Salah:</i> Menjawab \"Thank you\" dengan kata \"Please\". (Terjemahan harfiah dari \'silakan\' / \'kembali\' yang keliru).<br>\r\n  <i>Benar:</i> Jawablah dengan <b>\"You\'re welcome\"</b>, <b>\"My pleasure\"</b>, atau <b>\"Don\'t mention it\"</b>.</li>\r\n  <li><b>Ketertukaran \"Sorry\" dan \"Excuse Me\":</b><br>\r\n  <i>Salah:</i> Menabrak orang di lorong, lalu berkata \"Excuse me.\"<br>\r\n  <i>Benar:</i> Gunakan <b>\"I\'m sorry!\"</b> karena insiden tabrakan sudah telanjur terjadi.</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Gratitude:</b> Rasa syukur / Terima kasih</li>\r\n  <li><b>Apology:</b> Permohonan maaf / Penyesalan</li>\r\n  <li><b>Forgive:</b> Memaafkan</li>\r\n  <li><b>Appreciate:</b> Menghargai / Mengapresiasi</li>\r\n  <li><b>Inconvenience:</b> Ketidaknyamanan / Gangguan</li>\r\n  <li><b>Careless:</b> Ceroboh / Kurang hati-hati</li>\r\n  <li><b>Mention:</b> Menyebutkan (<i>\"Don\'t mention it\"</i> = Tak perlu berterima kasih kembali)</li>\r\n  <li><b>Pleasure:</b> Kesenangan / Suatu kehormatan (<i>\"My pleasure\"</i> = Dengan senang hati)</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n\r\n<p><b>A. Complete the sentences with the correct form of the verbs in brackets:</b></p>\r\n<ol>\r\n  <li>Thank you for ... (lend) me your colored pencils yesterday.</li>\r\n  <li>I must apologize for ... (break) your favorite mug, Aunt Linda.</li>\r\n  <li>Thanks a lot for ... (invite) me to your birthday party, Zahra!</li>\r\n  <li>Bagus is sorry for ... (not, finish) his group assignment on time.</li>\r\n</ol>\r\n\r\n<p><b>B. Choose the most appropriate response:</b></p>\r\n<ol>\r\n  <li><b>Aldi:</b> \"Thank you so much for walking my dog while I was away.\"<br>\r\n      <b>Bima:</b> \"...\"<br>\r\n      a. Excuse me.<br>\r\n      b. Don\'t mention it.<br>\r\n      c. I apologize.<br>\r\n      d. Never say that.</li>\r\n  <li><b>Citra:</b> \"I\'m really sorry, Sir. I forgot to bring my homework book today.\"<br>\r\n      <b>Teacher:</b> \"...\"<br>\r\n      a. You\'re welcome.<br>\r\n      b. My pleasure.<br>\r\n      c. That\'s too bad, but make sure to submit it tomorrow morning.<br>\r\n      d. Good morning, Citra.</li>\r\n</ol>\r\n\r\n<p><b>C. Rewrite the sentences correctly (Correct the errors):</b></p>\r\n<ol>\r\n  <li><i>Incorrect:</i> Thank you for bring this heavy box for me.<br>\r\n      <i>Correction:</i> ________________________________________</li>\r\n  <li><i>Incorrect:</i> When stepping on someone\'s foot by accident, say: \"Excuse me!\"<br>\r\n      <i>Correction:</i> ________________________________________</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(3,'Semester 1',1,3,'Vocabularies: Family','Mempelajari kosakata pohon keluarga (family tree) seperti orang tua, saudara kandung, kakek-nenek, paman, dan bibi.','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Vocabularies & Talking About Family (Family Members & Relationships)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Mengidentifikasi kosakata anggota keluarga inti (<i>nuclear family</i>) dan keluarga besar (<i>extended family</i>) dalam bahasa Inggris.</li>\r\n  <li>Memahami dan menerapkan struktur tata bahasa kepemilikan (<i>Possessive Adjectives</i> dan <i>Possessive \'s</i>) secara akurat saat menjelaskan hubungan kekerabatan.</li>\r\n  <li>Membaca serta menginterpretasikan bagan silsilah keluarga (<i>family tree</i>).</li>\r\n  <li>Menyusun teks deskriptif pendek serta memperagakan percakapan seputar mengenalkan dan menceritakan anggota keluarga kepada orang lain.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. Definition of Family:</b><br>\r\nDalam sosiologi dan studi bahasa, keluarga dikelompokkan ke dalam dua kategori utama:</p>\r\n<ul>\r\n  <li><b>Nuclear Family (Keluarga Inti):</b> Unit keluarga terkecil yang umumnya terdiri atas orang tua (ayah dan ibu) beserta anak-anak kandung atau angkat.</li>\r\n  <li><b>Extended Family (Keluarga Besar):</b> Hubungan kekeluargaan yang lebih luas di luar keluarga inti, mencakup kakek-nenek, paman, bibi, keponakan, sepupu, hingga keluarga karena hubungan pernikahan (<i>in-laws</i>).</li>\r\n</ul>\r\n\r\n<p><b>B. Family Tree (Pohon Silsilah Keluarga):</b><br>\r\nBagan diagram yang menggambarkan hubungan keturunan dan pernikahan antar-generasi dalam sebuah keluarga (dari kakek-nenek hingga anak atau cucu).</p>\r\n\r\n<h3>3. Rumus & Tata Bahasa Penting (Grammar Focus: Expressing Possession)</h3>\r\n<p>Untuk menjelaskan silsilah dan hubungan keluarga, terdapat 2 pola tata bahasa utama yang wajib dikuasai:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Pola Tata Bahasa</th>\r\n    <th>Rumus / Formula</th>\r\n    <th>Contoh Kalimat</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Possessive \'s (Apostrof Kepemilikan Tunggal)</b></td>\r\n    <td><i>[Nama Pemilik] + \'s + [Anggota Keluarga]</i></td>\r\n    <td>\"Budi is <b>Dewi\'s</b> brother.\" (Budi adalah saudara laki-lakinya Dewi)</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Possessive \' (Nama Berakhiran -s)</b></td>\r\n    <td><i>[Nama berakhiran s] + \' + [Anggota Keluarga]</i></td>\r\n    <td>\"Bagas is <b>Carlos\'</b> nephew.\" (Bagas adalah keponakan laki-lakinya Carlos)</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Possessive Adjectives</b></td>\r\n    <td><i>[My / Your / His / Her / Our / Their] + [Noun]</i></td>\r\n    <td>\"<b>His</b> father is a doctor. <b>Our</b> parents are friendly.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Menanyakan Hubungan Keluarga</b></td>\r\n    <td><i>Who is + [Subject]? / How is [A] related to [B]?</i></td>\r\n    <td>\"Who is Mrs. Rina?\" &rarr; \"She is <b>my aunt</b>.\"</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Daftar Kosakata Lengkap (Comprehensive Family Vocabularies)</h3>\r\n\r\n<p><b>A. The Nuclear Family (Keluarga Inti):</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>English Term</th>\r\n    <th>Part of Speech / Pronunciation</th>\r\n    <th>Indonesian Meaning</th>\r\n    <th>Informal / Calling Term</th>\r\n  </tr>\r\n  <tr>\r\n    <td>Parents</td>\r\n    <td>Noun (Plural)</td>\r\n    <td>Orang tua (ayah & ibu)</td>\r\n    <td>Mom and Dad</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Father</td>\r\n    <td>Noun (Male)</td>\r\n    <td>Ayah</td>\r\n    <td>Dad, Daddy, Papa</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Mother</td>\r\n    <td>Noun (Female)</td>\r\n    <td>Ibu</td>\r\n    <td>Mom, Mummy, Mama</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Child / Children</td>\r\n    <td>Noun (Singular / Plural)</td>\r\n    <td>Anak / Anak-anak</td>\r\n    <td>Kids</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Son</td>\r\n    <td>Noun (Male)</td>\r\n    <td>Anak laki-laki</td>\r\n    <td>-</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Daughter</td>\r\n    <td>Noun (Female)</td>\r\n    <td>Anak perempuan</td>\r\n    <td>-</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Brother</td>\r\n    <td>Noun (Male)</td>\r\n    <td>Saudara kandung laki-laki</td>\r\n    <td>Bro</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Sister</td>\r\n    <td>Noun (Female)</td>\r\n    <td>Saudara kandung perempuan</td>\r\n    <td>Sis</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Sibling(s)</td>\r\n    <td>Noun (Gender-neutral)</td>\r\n    <td>Saudara kandung</td>\r\n    <td>-</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Only child</td>\r\n    <td>Noun phrase</td>\r\n    <td>Anak tunggal</td>\r\n    <td>-</td>\r\n  </tr>\r\n</table>\r\n\r\n<p><b>B. The Extended Family (Keluarga Besar):</b></p>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>English Term</th>\r\n    <th>Indonesian Meaning</th>\r\n    <th>Penjelasan Hubungan</th>\r\n  </tr>\r\n  <tr>\r\n    <td>Grandparents</td>\r\n    <td>Kakek dan Nenek</td>\r\n    <td>Orang tua dari ayah atau ibu kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Grandfather / Grandpa</td>\r\n    <td>Kakek</td>\r\n    <td>Ayah dari ayah atau ibu kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Grandmother / Grandma</td>\r\n    <td>Nenek</td>\r\n    <td>Ibu dari ayah atau ibu kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Grandchild / Grandchildren</td>\r\n    <td>Cucu / Cucu-cucu</td>\r\n    <td>Anak dari anak kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Grandson / Granddaughter</td>\r\n    <td>Cucu laki-laki / Cucu perempuan</td>\r\n    <td>Cucu spesifik berdasarkan jenis kelamin</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Uncle</td>\r\n    <td>Paman / Om</td>\r\n    <td>Saudara laki-laki dari ayah atau ibu kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Aunt</td>\r\n    <td>Bibi / Tante</td>\r\n    <td>Saudara perempuan dari ayah atau ibu kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Cousin</td>\r\n    <td>Sepupu (laki-laki / perempuan)</td>\r\n    <td>Anak dari paman atau bibi kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Nephew</td>\r\n    <td>Keponakan laki-laki</td>\r\n    <td>Anak laki-laki dari saudara kandung kita</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Niece</td>\r\n    <td>Keponakan perempuan</td>\r\n    <td>Anak perempuan dari saudara kandung kita</td>\r\n  </tr>\r\n</table>\r\n\r\n<p><b>C. In-Laws and Stepfamily (Keluarga Semenda & Sambung):</b></p>\r\n<ul>\r\n  <li><b>Father-in-law:</b> Ayah mertua | <b>Mother-in-law:</b> Ibu mertua</li>\r\n  <li><b>Brother-in-law:</b> Saudara ipar laki-laki | <b>Sister-in-law:</b> Saudara ipar perempuan</li>\r\n  <li><b>Son-in-law:</b> Menantu laki-laki | <b>Daughter-in-law:</b> Menantu perempuan</li>\r\n  <li><b>Stepfather / Stepmother:</b> Ayah tiri / Ibu tiri</li>\r\n  <li><b>Stepbrother / Stepsister:</b> Saudara tiri laki-laki / Saudara tiri perempuan</li>\r\n</ul>\r\n\r\n<h3>5. Contoh Teks Deskripsi Singkat (Descriptive Text: My Family)</h3>\r\n<p>\r\n<i>\"Hello everyone! My name is Raditya, and I would like to introduce my family. I live in an energetic household of five people. My father\'s name is Mr. Hendra; he is a hardworking junior high school teacher. My mother, Mrs. Sarah, is a talented baker who runs a home pastry shop. I have an elder brother named Arya and a younger sister named Shifa. Arya is a high school student who loves basketball, while Shifa is still in elementary school. On weekends, we often visit our grandparents in the countryside. I love my family very much because they always support me in everything I do.\"</i>\r\n</p>\r\n\r\n<h3>6. Contoh Percakapan Interaktif (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Looking at a Family Photo (Melihat Foto Keluarga)</b><br>\r\n<i>Situasi: Farel sedang berkunjung ke rumah Galang dan melihat foto berbingkai di dinding ruang tamu.</i></p>\r\n<p>\r\n<b>Farel:</b> \"Wow, you have a lovely family picture on the wall, Galang! Is this handsome boy next to you your brother?\"<br>\r\n<b>Galang:</b> \"Yes, that is my elder brother, Danu. He is two years older than me.\"<br>\r\n<b>Farel:</b> \"I see! And who are the cheerful couple in the middle?\"<br>\r\n<b>Galang:</b> \"Those are my parents. My father is an accountant, and my mother is a nurse at the central hospital.\"<br>\r\n<b>Farel:</b> \"What about the cute little girl wearing a red hat?\"<br>\r\n<b>Galang:</b> \"That is my little cousin, Nayla. She is Uncle Bram\'s daughter. She visits our house almost every Sunday.\"<br>\r\n<b>Farel:</b> \"What a warm and happy family you have!\"<br>\r\n<b>Galang:</b> \"Thank you, Farel!\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Asking About Siblings (Menanyakan Saudara Kandung)</b><br>\r\n<i>Situasi: Sarah dan Amira mengobrol santai di bangku taman sekolah.</i></p>\r\n<p>\r\n<b>Sarah:</b> \"Do you have any brothers or sisters, Amira?\"<br>\r\n<b>Amira:</b> \"No, I don\'t. I am an only child, so there are just my parents and me at home. How about you?\"<br>\r\n<b>Sarah:</b> \"I come from a big family! I have two brothers and one elder sister. My house is always noisy and crowded.\"<br>\r\n<b>Amira:</b> \"That sounds really exciting. You must never feel lonely at home.\"<br>\r\n<b>Sarah:</b> \"That\'s true! Sometimes we fight over the TV remote, but we care for each other deeply.\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Ketertukaran Antara Nephew dan Niece:</b><br>\r\n  <i>Salah:</i> \"My sister had a baby girl, so now I have a <u>nephew</u>.\"<br>\r\n  <i>Benar:</i> \"My sister had a baby girl, so now I have a <b>niece</b>.\" (Ingat: <i>nephew</i> = keponakan laki-laki; <i>niece</i> = keponakan perempuan).</li>\r\n  <li><b>Penggunaan Istilah \"Cousin\":</b><br>\r\n  Di Indonesia sering disebut \'sepupu laki-laki\' atau \'sepupu perempuan\'. Namun dalam bahasa Inggris, tidak ada kata <i>cousiness</i> atau <i>cousin-boy</i>. Cukup gunakan kata <b>cousin</b> untuk kedua gender.</li>\r\n  <li><b>Kesalahan Tanda Kepemilikan (Possessive \'s vs. Plural):</b><br>\r\n  <i>Salah:</i> \"This is my <u>mothers</u> car.\" (Bermakna ibu berjumlah banyak).<br>\r\n  <i>Benar:</i> \"This is my <b>mother\'s</b> car.\" (Menggunakan tanda kutip tunggal atas sebelum huruf <i>s</i> untuk menandakan kepemilikan).</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Relative:</b> Sanak saudara / Kerabat</li>\r\n  <li><b>Ancestor:</b> Nenek moyang / Leluhur</li>\r\n  <li><b>Generation:</b> Generasi / Angkatan usia</li>\r\n  <li><b>Elder / Older:</b> Lebih tua (misal: <i>elder sister</i> = kakak perempuan)</li>\r\n  <li><b>Younger:</b> Lebih muda (misal: <i>younger brother</i> = adik laki-laki)</li>\r\n  <li><b>Twins:</b> Anak kembar</li>\r\n  <li><b>Spouse:</b> Pasangan resmi (suami atau istri)</li>\r\n  <li><b>Marital status:</b> Status pernikahan</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n\r\n<p><b>A. Read the clues and determine the family member:</b></p>\r\n<ol>\r\n  <li>Your mother\'s sister is your ...</li>\r\n  <li>Your father\'s father is your ...</li>\r\n  <li>Your brother\'s son is your ...</li>\r\n  <li>Your aunt\'s children are your ...</li>\r\n  <li>A person who has no brothers and no sisters is an ...</li>\r\n</ol>\r\n\r\n<p><b>B. Complete the sentences using possessive (\'s) correctly:</b></p>\r\n<ol>\r\n  <li>This is my ... (father) motorcycle. He rides it to work every day.</li>\r\n  <li>Siti is ... (Rahmat) daughter.</li>\r\n  <li>We are going to my ... (grandparents) house this weekend.</li>\r\n</ol>\r\n\r\n<p><b>C. Translation Exercise (Terjemahkan ke dalam Bahasa Inggris):</b></p>\r\n<ol>\r\n  <li>Paman saya tinggal di Bandung bersama istrinya. &rarr; ________________________________________</li>\r\n  <li>Apakah kamu punya saudara kandung? &rarr; ________________________________________</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(4,'Semester 1',1,4,'Introduction to Verb','Mengenal kata kerja (action verbs) dalam bahasa Inggris dan penggunaannya dalam kalimat sederhana.','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Introduction to Verbs (Action Verbs, Linking/Be Verbs, & Subject-Verb Agreement)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Memahami fungsi dan kedudukan kata kerja (<i>verb</i>) sebagai predikat inti dalam kalimat bahasa Inggris.</li>\r\n  <li>Membedakan kata kerja tindakan (<i>action verbs</i>) dan kata kerja penghubung (<i>linking verbs / to be</i>).</li>\r\n  <li>Menerapkan aturan kesesuaian subjek dan kata kerja (<i>Subject-Verb Agreement</i>) pada kalimat waktu sekarang (<i>Simple Present Tense</i>).</li>\r\n  <li>Menguasai kaidah penambahan akhiran <i>-s/-es</i> untuk subjek tunggal orang ketiga (<i>He, She, It</i>).</li>\r\n  <li>Menyusun kalimat sederhana serta menggunakan kata kerja secara tepat dalam dialog sehari-hari.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. What is a Verb?</b><br>\r\n<i>Verb</i> (kata kerja) adalah kelas kata yang digunakan untuk menyatakan suatu tindakan (<i>action</i>), keadaan atau eksistensi (<i>state of being</i>), atau kejadian (<i>occurrence</i>). Tanpa kata kerja, sebuah susunan kata tidak dapat dianggap sebagai satu kalimat utuh dalam bahasa Inggris.</p>\r\n\r\n<p><b>B. Dua Kategori Utama Verb untuk Kelas 7:</b></p>\r\n<ul>\r\n  <li><b>Action Verbs:</b> Kata kerja yang menggambarkan aksi fisik atau mental yang dilakukan oleh subjek. Contoh: <i>run, study, eat, write, think</i>.</li>\r\n  <li><b>Linking Verbs (khususnya \"To Be\"):</b> Kata kerja yang tidak menunjukkan gerakan fisik, melainkan menghubungkan subjek dengan kata sifat (<i>adjective</i>), kata benda (<i>noun</i>), atau keterangan tempat (<i>adverb of place</i>). Contoh: <i>is, am, are</i>.</li>\r\n</ul>\r\n\r\n<h3>3. Rumus & Aturan Tata Bahasa (Subject-Verb Agreement)</h3>\r\n<p>Kunci terpenting dalam memahami kata kerja di kelas 7 adalah <b>kesesuaian antara subjek dan kata kerjanya</b> pada bentuk dasar (<i>Present Tense</i>):</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori Subjek</th>\r\n    <th>Subjek (Pronoun)</th>\r\n    <th>Linking Verb (To Be)</th>\r\n    <th>Pola Action Verb</th>\r\n    <th>Contoh Kalimat</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Plural & First/Second Person</b></td>\r\n    <td>I, You, We, They, [2 Orang/Benda]</td>\r\n    <td>am (khusus I), are (You/We/They)</td>\r\n    <td><b>Verb 1 (Base Form)</b><br><i>(Tanpa tambahan akhiran)</i></td>\r\n    <td>\"They <b>study</b> English.\"<br>\"We <b>are</b> students.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Singular Third Person</b></td>\r\n    <td>He, She, It, [1 Orang/Nama Tunggal]</td>\r\n    <td>is</td>\r\n    <td><b>Verb 1 + s / es / ies</b><br><i>(Wajib berakhiran -s/-es)</i></td>\r\n    <td>\"He <b>studies</b> English.\"<br>\"She <b>is</b> clever.\"</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Aturan Penambahan Akhiran -s, -es, dan -ies pada Verb</h3>\r\n<p>Bila subjeknya adalah orang ketiga tunggal (<b>He, She, It</b> atau satu nama seperti <i>Budi, My cat</i>), kata kerja mengalami penyesuaian ejaan berikut:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kondisi Akhiran Kata Kerja</th>\r\n    <th>Aturan Perubahan</th>\r\n    <th>Contoh Base Verb &rarr; Verb + s/es</th>\r\n  </tr>\r\n  <tr>\r\n    <td>Sebagian besar kata kerja umum</td>\r\n    <td>Cukup tambahkan <b>-s</b></td>\r\n    <td>read &rarr; <b>reads</b>, speak &rarr; <b>speaks</b>, drink &rarr; <b>drinks</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td>Berakhiran huruf mendesir: <b>-ch, -sh, -ss, -x, -z, -o</b></td>\r\n    <td>Tambahkan <b>-es</b></td>\r\n    <td>watch &rarr; <b>watches</b>, wash &rarr; <b>washes</b>, kiss &rarr; <b>kisses</b>, fix &rarr; <b>fixes</b>, go &rarr; <b>goes</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td>Berakhiran huruf <b>konsonan + y</b></td>\r\n    <td>Ubah <b>y</b> menjadi <b>-ies</b></td>\r\n    <td>study &rarr; <b>studies</b>, fly &rarr; <b>flies</b>, cry &rarr; <b>cries</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td>Berakhiran huruf <b>vokal + y</b></td>\r\n    <td>Hanya tambahkan <b>-s</b> (jangan ubah huruf y)</td>\r\n    <td>play &rarr; <b>plays</b>, buy &rarr; <b>buys</b>, enjoy &rarr; <b>enjoys</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td>Kata kerja tak beraturan khusus</td>\r\n    <td>Bentuk berubah mandiri</td>\r\n    <td>have &rarr; <b>has</b></td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>5. Daftar Kosakata Kata Kerja Harian (Daily Routine Action Verbs)</h3>\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Base Verb (V1)</th>\r\n    <th>Meaning (Arti)</th>\r\n    <th>He / She / It Form</th>\r\n    <th>Contoh Kalimat Sederhana</th>\r\n  </tr>\r\n  <tr>\r\n    <td>Wake up</td>\r\n    <td>Bangun tidur</td>\r\n    <td>Wakes up</td>\r\n    <td>I wake up at 5 a.m. / She wakes up at 5 a.m.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Eat</td>\r\n    <td>Makan</td>\r\n    <td>Eats</td>\r\n    <td>They eat fried rice for breakfast.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Drink</td>\r\n    <td>Minum</td>\r\n    <td>Drinks</td>\r\n    <td>He drinks warm milk before bed.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Go</td>\r\n    <td>Pergi</td>\r\n    <td>Goes</td>\r\n    <td>We go to school by bicycle. / Aldo goes by bus.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Write</td>\r\n    <td>Menulis</td>\r\n    <td>Writes</td>\r\n    <td>She writes an essay in her notebook.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Listen</td>\r\n    <td>Mendengarkan</td>\r\n    <td>Listens</td>\r\n    <td>The students listen to the teacher attentively.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Play</td>\r\n    <td>Bermain</td>\r\n    <td>Plays</td>\r\n    <td>Rian plays badminton every Sunday.</td>\r\n  </tr>\r\n  <tr>\r\n    <td>Help</td>\r\n    <td>Membantu / Menolong</td>\r\n    <td>Helps</td>\r\n    <td>I help my mother clean the living room.</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>6. Contoh Percakapan Interaktif (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Talking About Daily Routines (Membahas Rutinitas Harian)</b><br>\r\n<i>Situasi: Dita dan Arman saling bertanya tentang kegiatan mereka setelah pulang sekolah.</i></p>\r\n<p>\r\n<b>Dita:</b> \"What do you usually do after school, Arman?\"<br>\r\n<b>Arman:</b> \"I take a quick shower, have lunch, and then I do my homework.\"<br>\r\n<b>Dita:</b> \"Does your brother help you with your homework?\"<br>\r\n<b>Arman:</b> \"No, he doesn\'t. He plays basketball at the community court until late afternoon.\"<br>\r\n<b>Dita:</b> \"I see. As for me, I usually practice the piano for one hour and help my mother bake cakes.\"<br>\r\n<b>Arman:</b> \"That sounds productive! You really spend your afternoon well.\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Using Linking Verbs vs. Action Verbs in the Classroom</b><br>\r\n<i>Situasi: Bu Erika menanyakan aktivitas kelompok kepada Gilang dan Tari.</i></p>\r\n<p>\r\n<b>Mrs. Erika:</b> \"Are you both ready for the reading presentation?\"<br>\r\n<b>Gilang:</b> \"Yes, Ma\'am! We are ready. Tari holds the poster, and I read the summary aloud.\"<br>\r\n<b>Mrs. Erika:</b> \"Excellent coordination. Is the microphone working properly?\"<br>\r\n<b>Tari:</b> \"Yes, it is. The sound comes out clearly.\"<br>\r\n<b>Mrs. Erika:</b> \"Good. Begin your presentation now, please.\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Double Verb (Menumpuk \"To Be\" dan \"Action Verb\" Dasar):</b><br>\r\n  <i>Salah:</i> \"I <u>am go</u> to school.\" atau \"She <u>is sleep</u> in the bedroom.\"<br>\r\n  <i>Benar:</i> \"I <b>go</b> to school.\" dan \"She <b>sleeps</b> in the bedroom.\" (Pilih salah satu: gunakan <i>Action Verb</i> atau gunakan <i>To Be</i> jika diikuti kata sifat/benda).</li>\r\n  <li><b>Lupa Menambahkan Akhiran -s/-es pada Subjek Tunggal:</b><br>\r\n  <i>Salah:</i> \"My father <u>drive</u> a blue car.\"<br>\r\n  <i>Benar:</i> \"My father <b>drives</b> a blue car.\" (Karena <i>My father</i> setara dengan <i>He</i>).</li>\r\n  <li><b>Keliru Mengubah Kata Kerja Berakhiran Vokal + Y:</b><br>\r\n  <i>Salah:</i> \"He <u>plaies</u> football every Friday.\"<br>\r\n  <i>Benar:</i> \"He <b>plays</b> football every Friday.\" (Huruf sebelum <b>y</b> adalah vokal <b>a</b>, jadi hanya perlu ditambah <b>-s</b>).</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Verb:</b> Kata kerja (inti predikat dalam kalimat)</li>\r\n  <li><b>Action Verb:</b> Kata kerja tindakan fisik atau proses mental</li>\r\n  <li><b>Linking Verb:</b> Kata kerja penghubung identitas atau keadaan subjek</li>\r\n  <li><b>Subject-Verb Agreement:</b> Kesesuaian bentuk kata kerja dengan subjeknya</li>\r\n  <li><b>Base form (V1):</b> Bentuk dasar kata kerja tanpa imbuhan</li>\r\n  <li><b>Habitual action:</b> Tindakan yang dilakukan berulang-ulang / kebiasaan</li>\r\n  <li><b>Pronoun:</b> Kata ganti orang atau benda (<i>I, You, We, They, He, She, It</i>)</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n\r\n<p><b>A. Choose the correct verb form in the parentheses:</b></p>\r\n<ol>\r\n  <li>Mr. Roni ... (teach / teaches) science at Nusantara Junior High School.</li>\r\n  <li>The students ... (listen / listens) carefully to the teacher\'s explanation.</li>\r\n  <li>Diana always ... (wash / washes) her hands before eating lunch.</li>\r\n  <li>My cat ... (catch / catches) mice in the kitchen at night.</li>\r\n  <li>We ... (walk / walks) to school together every morning.</li>\r\n</ol>\r\n\r\n<p><b>B. Fill in the blanks with \"is\", \"am\", or \"are\":</b></p>\r\n<ol>\r\n  <li>I ... a seventh-grade student.</li>\r\n  <li>Doni and Riko ... my close friends.</li>\r\n  <li>The library ... quiet and comfortable for reading.</li>\r\n</ol>\r\n\r\n<p><b>C. Error Correction (Benahi kalimat yang salah):</b></p>\r\n<ol>\r\n  <li><i>Incorrect:</i> She is like fresh orange juice.<br>\r\n      <i>Correction:</i> ________________________________________</li>\r\n  <li><i>Incorrect:</i> Bagas study in his room every evening.<br>\r\n      <i>Correction:</i> ________________________________________</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(5,'Semester 1',1,5,'Introduction to Pronoun','Mengenal kata ganti orang (Personal Pronouns) sebagai subjek dan objek serta kata ganti kepemilikan (Possessive Adjectives).','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Introduction to Personal Pronouns (Subject, Object, Possessive Adjective, Possessive Pronoun)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Memahami definisi dan fungsi <i>pronoun</i> (kata ganti) untuk menghindari pengulangan kata benda (<i>repetition</i>).</li>\r\n  <li>Membedakan empat bentuk kata ganti persona: <i>Subject Pronoun</i>, <i>Object Pronoun</i>, <i>Possessive Adjective</i>, dan <i>Possessive Pronoun</i>.</li>\r\n  <li>Menempatkan posisi kata ganti secara tepat sesuai struktur sintaksis kalimat (sebelum kata kerja, sesudah kata kerja/preposisi, atau sebelum kata benda).</li>\r\n  <li>Menyusun kalimat serta menganalisis kesalahan umum penggunaan kata ganti dalam teks interaksi interpersonal maupun transaksional.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. What is a Pronoun?</b><br>\r\n<i>Pronoun</i> (kata ganti) adalah kata yang digunakan untuk menggantikan kata benda (<i>noun</i>), baik berupa orang (<i>people</i>), hewan (<i>animals</i>), tempat (<i>places</i>), maupun benda mati (<i>things</i>). Penggunaan kata ganti bertujuan membuat kalimat lebih efektif, ringkas, dan tidak monoton akibat pengulangan nama subjek atau objek secara berlebihan.</p>\r\n\r\n<p><b>B. Contoh Perbandingan:</b></p>\r\n<ul>\r\n  <li><i>Tanpa Pronoun (Berulang):</i> \"<b>Rani</b> brings <b>Rani\'s</b> bag because <b>Rani</b> wants to study with <b>Budi and Edo</b>.\" (Kaku dan tidak natural).</li>\r\n  <li><i>Dengan Pronoun:</i> \"<b>She</b> brings <b>her</b> bag because <b>she</b> wants to study with <b>them</b>.\" (Lancar dan alami).</li>\r\n</ul>\r\n\r\n<h3>3. Tabel Klasifikasi Lengkap Personal Pronouns</h3>\r\n<p>Berikut adalah tabel acuan empat bentuk kata ganti persona yang wajib dikuasai siswa kelas 7:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Orang ke- / Sudut Pandang</th>\r\n    <th>Subject Pronoun<br><i>(Pelaku tindakan)</i></th>\r\n    <th>Object Pronoun<br><i>(Penerima tindakan)</i></th>\r\n    <th>Possessive Adjective<br><i>(Wajib + Kata Benda)</i></th>\r\n    <th>Possessive Pronoun<br><i>(Mandiri tanpa benda)</i></th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>1st Person Sing. (Saya)</b></td>\r\n    <td>I</td>\r\n    <td>me</td>\r\n    <td>my + noun</td>\r\n    <td>mine</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>2nd Person (Kamu / Kalian)</b></td>\r\n    <td>you</td>\r\n    <td>you</td>\r\n    <td>your + noun</td>\r\n    <td>yours</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>3rd Person Sing. Male (Dia lk)</b></td>\r\n    <td>he</td>\r\n    <td>him</td>\r\n    <td>his + noun</td>\r\n    <td>his</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>3rd Person Sing. Female (Dia pr)</b></td>\r\n    <td>she</td>\r\n    <td>her</td>\r\n    <td>her + noun</td>\r\n    <td>hers</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>3rd Person Sing. Neutral (Benda/Hewan)</b></td>\r\n    <td>it</td>\r\n    <td>it</td>\r\n    <td>its + noun</td>\r\n    <td><i>(jarang dipakai)</i></td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>1st Person Plural (Kita / Kami)</b></td>\r\n    <td>we</td>\r\n    <td>us</td>\r\n    <td>our + noun</td>\r\n    <td>ours</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>3rd Person Plural (Mereka)</b></td>\r\n    <td>they</td>\r\n    <td>them</td>\r\n    <td>their + noun</td>\r\n    <td>theirs</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Rumus & Aturan Posisi dalam Kalimat (Grammar Rules)</h3>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Bentuk Pronoun</th>\r\n    <th>Rumus / Posisi Sintaksis</th>\r\n    <th>Penjelasan Singkat & Contoh</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Subject Pronoun</b></td>\r\n    <td><i>[Subject Pronoun] + [Verb]</i></td>\r\n    <td>Terletak di awal klausa sebelum predikat.<br>Contoh: \"<b>They</b> play badminton every Friday.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Object Pronoun</b></td>\r\n    <td><i>[Verb / Preposition] + [Object Pronoun]</i></td>\r\n    <td>Terletak setelah kata kerja aktif atau preposisi (<i>with, for, to, at</i>).<br>Contoh: \"Mr. Budi called <b>him</b>.\" / \"Listen to <b>me</b>!\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Possessive Adjective</b></td>\r\n    <td><i>[Possessive Adj.] + [Noun]</i></td>\r\n    <td><b>Tidak bisa berdiri sendiri</b>, wajib diikuti kata benda yang dimiliki.<br>Contoh: \"This is <b>her</b> pencil case.\"</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Possessive Pronoun</b></td>\r\n    <td><i>[Noun Phrase] + [is/are] + [Possessive Pronoun]</i></td>\r\n    <td><b>Berdiri sendiri</b>, menggantikan kata benda kepemilikan seutuhnya.<br>Contoh: \"This pencil case is <b>hers</b>.\" (hers = her pencil case)</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>5. Penjelasan Mendalam (In-Depth Explanation)</h3>\r\n\r\n<p><b>A. Perbedaan Antara \"Her\" (Object) dan \"Her\" (Possessive Adjective):</b></p>\r\n<ul>\r\n  <li>Kata <i>her</i> memiliki dua peran berbeda. Cara membedakannya adalah melihat posisinya di kalimat:\r\n    <ul>\r\n      <li>Sebagai <b>Object</b> jika berada setelah kata kerja: \"I see <b>her</b> at the canteen.\"</li>\r\n      <li>Sebagai <b>Possessive Adjective</b> jika langsung menempel di depan kata benda: \"That is <b>her</b> bicycle.\"</li>\r\n    </ul>\r\n  </li>\r\n</ul>\r\n\r\n<p><b>B. Perbedaan Antara \"Its\" dan \"It\'s\":</b></p>\r\n<ul>\r\n  <li><b>Its (tanpa apostrof):</b> Bentuk kepemilikan untuk hewan atau benda mati. Contoh: \"The cat licks <b>its</b> fur.\" (Kucing itu menjilati bulunya).</li>\r\n  <li><b>It\'s (dengan apostrof):</b> Singkatan dari <i>it is</i> atau <i>it has</i>. Contoh: \"<b>It\'s</b> a sunny morning.\" (Hari ini cerah).</li>\r\n</ul>\r\n\r\n<h3>6. Contoh Percakapan Interaktif (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Borrowing Stationery (Meminjam Alat Tulis di Kelas)</b><br>\r\n<i>Situasi: Dimas sedang mencari penghapusnya saat jam pelajaran Bahasa Inggris, lalu bertanya kepada Anita.</i></p>\r\n<p>\r\n<b>Dimas:</b> \"Excuse me, Anita. Have you seen my eraser? I cannot find it in my pencil box.\"<br>\r\n<b>Anita:</b> \"Is this blue one yours, Dimas?\"<br>\r\n<b>Dimas:</b> \"No, that is not mine. Mine has a white paper cover.\"<br>\r\n<b>Anita:</b> \"Oh, look under Rian\'s desk! I think he dropped it accidentally.\"<br>\r\n<b>Dimas:</b> \"Yes, you are right. That is my eraser! Thank you, Anita.\"<br>\r\n<b>Anita:</b> \"Don\'t mention it. Go grab it before someone steps on it.\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: Talking About New Classmates (Membicarakan Teman Sekelas Baru)</b><br>\r\n<i>Situasi: Galih dan Farhan duduk di kantin membicarakan dua murid pindahan.</i></p>\r\n<p>\r\n<b>Galih:</b> \"Do you know the new students in class 7B? Their names are Kevin and Jason.\"<br>\r\n<b>Farhan:</b> \"Yes, I saw them this morning. Mr. Danang introduced them in the hall.\"<br>\r\n<b>Galih:</b> \"Where do they live? Do you know?\"<br>\r\n<b>Farhan:</b> \"They live near our school. Their house is right behind the post office. We can invite them to play soccer with us.\"<br>\r\n<b>Galih:</b> \"Great idea! Let\'s talk to them after the final bell.\"\r\n</p>\r\n\r\n<p><b>Dialogue 3: Lost Item (Barang Ketinggalan)</b><br>\r\n<i>Situasi: Bu Sarah menemukan jaket di ruang guru dan menanyakan kepada Citra.</i></p>\r\n<p>\r\n<b>Mrs. Sarah:</b> \"Citra, is this jacket yours?\"<br>\r\n<b>Citra:</b> \"No, Ma\'am, it is not mine. Mine is navy blue, while this one is red.\"<br>\r\n<b>Mrs. Sarah:</b> \"Do you know who owns it?\"<br>\r\n<b>Citra:</b> \"I think it belongs to Tari. Her locker is right next to mine, and she wore a red jacket earlier.\"<br>\r\n<b>Mrs. Sarah:</b> \"Alright, I will keep it here until she claims it. Thank you for your help.\"<br>\r\n<b>Citra:</b> \"You are welcome, Mrs. Sarah.\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Menaruh Subject Pronoun di Posisi Objek:</b><br>\r\n  <i>Salah:</i> \"Teacher saw <u>I</u> and <u>she</u> in the library.\"<br>\r\n  <i>Benar:</i> \"Teacher saw <b>me</b> and <b>her</b> in the library.\" (Setelah kata kerja <i>saw</i>, wajib memakai bentuk objek).</li>\r\n  <li><b>Menambahkan Kata Benda Setelah Possessive Pronoun:</b><br>\r\n  <i>Salah:</i> \"This is <u>mine book</u>.\" atau \"That is <u>hers bag</u>.\"<br>\r\n  <i>Benar:</i> \"This is <b>my book</b>\" (atau \"This book is <b>mine</b>\") dan \"That is <b>her bag</b>\" (atau \"That bag is <b>hers</b>\").</li>\r\n  <li><b>Keliru Menggunakan \"Its\" vs. \"It\'s\":</b><br>\r\n  <i>Salah:</i> \"The bird builds <u>it\'s</u> nest.\" (Artinya rancu: Burung itu membangun <i>ia adalah</i> sarang).<br>\r\n  <i>Benar:</i> \"The bird builds <b>its</b> nest.\"</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Pronoun:</b> Kata ganti benda atau orang</li>\r\n  <li><b>Subject:</b> Pelaku utama tindakan dalam kalimat</li>\r\n  <li><b>Object:</b> Sasaran atau pihak yang menerima tindakan</li>\r\n  <li><b>Possession:</b> Kepemilikan / Hak milik</li>\r\n  <li><b>Belong to:</b> Milik / Kepunyaan (contoh: <i>It belongs to me</i> = Benda itu milikku)</li>\r\n  <li><b>Replace:</b> Menggantikan</li>\r\n  <li><b>Antecedent:</b> Kata benda awal yang digantikan oleh kata ganti</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n\r\n<p><b>A. Choose the correct pronoun in brackets:</b></p>\r\n<ol>\r\n  <li>Mrs. Laila gave ... (we / us) a math quiz this morning.</li>\r\n  <li>My brother loves playing guitar. ... (He / Him) practices every afternoon.</li>\r\n  <li>Don\'t touch that ruler! It is ... (my / mine).</li>\r\n  <li>The dog is wagging ... (its / it\'s) tail happily.</li>\r\n  <li>Rico and Aldo are late because ... (their / they) bus broke down.</li>\r\n</ol>\r\n\r\n<p><b>B. Complete the sentences with the appropriate Subject or Object Pronoun:</b></p>\r\n<ol>\r\n  <li>Nadia is very kind. Everyone in our class likes ... very much.</li>\r\n  <li>My parents are visiting our grandmother. ... will return home tomorrow.</li>\r\n  <li>I need your help with this box. Can you lift it with ...?</li>\r\n</ol>\r\n\r\n<p><b>C. Rewrite each sentence using a Possessive Pronoun (mine, yours, his, hers, ours, theirs):</b></p>\r\n<ol>\r\n  <li><i>Example:</i> This is our classroom. &rarr; <i>This classroom is ours.</i></li>\r\n  <li>That is her dictionary. &rarr; That dictionary is ...</li>\r\n  <li>These are your drawing pens. &rarr; These drawing pens are ...</li>\r\n  <li>Those are their sports uniforms. &rarr; Those sports uniforms are ...</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(6,'Semester 1',1,6,'Numbers (Cardinal & Ordinal)','Mempelajari perbedaan bilangan cacah/kuantitas (Cardinal Numbers) dan bilangan tingkat/urutan (Ordinal Numbers).','<header>\r\n  <h2>MODUL PEMBELAJARAN BAHASA INGGRIS KELAS 7 SMP</h2>\r\n  <p><b>Topik:</b> Numbers (Cardinal and Ordinal Numbers)<br>\r\n  <b>Alokasi Waktu:</b> 2 Pertemuan (4 x 40 Menit)<br>\r\n  <b>Fase / Semester:</b> Fase D / Ganjil</p>\r\n</header>\r\n\r\n<hr>\r\n\r\n<h3>1. Tujuan Pembelajaran</h3>\r\n<p>Setelah mempelajari modul ini, peserta didik diharapkan mampu:</p>\r\n<ul>\r\n  <li>Membedakan fungsi serta penggunaan angka hitung (<i>Cardinal Numbers</i>) dan angka tingkat/urutan (<i>Ordinal Numbers</i>).</li>\r\n  <li>Menulis ejaan angka bahasa Inggris dengan benar, termasuk angka belasan, puluhan, ratusan, hingga ribuan.</li>\r\n  <li>Menerapkan penggunaan <i>Ordinal Numbers</i> pada penyebutan tanggal (<i>dates</i>), urutan tingkatan kelas, lantai gedung, serta posisi juara dalam perlombaan.</li>\r\n  <li>Menyusun kalimat dan memperagakan percakapan seputar menanyakan kuantitas, harga, nomor telepon, dan tanggal lahir.</li>\r\n</ul>\r\n\r\n<h3>2. Definisi & Konsep Dasar</h3>\r\n<p><b>A. Cardinal Numbers (Bilangan Pokok/Hitung):</b><br>\r\n<i>Cardinal Numbers</i> adalah angka yang digunakan untuk menyatakan jumlah, kuantitas, atau banyaknya benda, orang, maupun hewan. Angka ini menjawab pertanyaan: <i>\"How many?\"</i> (Berapa banyak?) atau <i>\"How much?\"</i> (Berapa harga/banyaknya?). Contoh: <i>one, two, twenty-five, one hundred</i>.</p>\r\n\r\n<p><b>B. Ordinal Numbers (Bilangan Tingkat/Urutan):</b><br>\r\n<i>Ordinal Numbers</i> adalah angka yang menunjukkan urutan, tahapan, peringkat, posisi, atau penanggalan kalender. Angka ini menjawab pertanyaan: <i>\"Which one?\"</i> (Yang mana?) atau urutan ke berapa. Ciri khas penulisannya memakai akhiran kecil di atas atau di samping angka (<b>-st, -nd, -rd, -th</b>). Contoh: <i>first (1st), second (2nd), third (3rd), fourth (4th)</i>.</p>\r\n\r\n<h3>3. Aturan Pembentukan & Pola Ejaan (Spelling Rules)</h3>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>Kategori Angka</th>\r\n    <th>Aturan Pembentukan & Rumus</th>\r\n    <th>Contoh Ejaan</th>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Belasan (Teens: 13–19)</b></td>\r\n    <td><i>[Root word] + -teen</i><br>(Hati-hati perubahan bunyi huruf pada 13 dan 15)</td>\r\n    <td>13 = thir<b>teen</b><br>14 = four<b>teen</b><br>15 = fif<b>teen</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Puluhan (Tens: 20, 30, ... 90)</b></td>\r\n    <td><i>[Root word] + -ty</i></td>\r\n    <td>20 = twen<b>ty</b><br>30 = thir<b>ty</b><br>50 = fif<b>ty</b></td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Puluhan Kombinasi (21–99)</b></td>\r\n    <td>Gunakan tanda hubung (<b>hyphen</b>) di antara puluhan dan satuan</td>\r\n    <td>21 = twenty<b>-</b>one<br>45 = forty<b>-</b>five<br>99 = ninety<b>-</b>nine</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Ratusan & Ribuan</b></td>\r\n    <td><i>[Angka] + hundred / thousand</i><br>(Jangan ditambah -s jika ada jumlah pasti di depannya)</td>\r\n    <td>300 = three hundred<br>1.500 = one thousand five hundred</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Ordinal Akhiran -st, -nd, -rd</b></td>\r\n    <td>Khusus angka 1 (first), 2 (second), 3 (third), dan kombinasinya (kecuali 11, 12, 13)</td>\r\n    <td>1st, 2nd, 3rd, 21st, 22nd, 23rd, 31st</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Ordinal Akhiran -th</b></td>\r\n    <td>Angka 4 sampai 20, serta semua angka puluhan bulat</td>\r\n    <td>4th, 7th, 11th, 12th, 20th (twentie<b>th</b>)</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>4. Tabel Perbandingan Cardinal vs. Ordinal (1–31)</h3>\r\n<p>Daftar 1 hingga 31 sangat penting karena menjadi dasar penyebutan hari dan tanggal dalam sebulan:</p>\r\n\r\n<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\">\r\n  <tr>\r\n    <th>No</th>\r\n    <th>Cardinal Number</th>\r\n    <th>Ordinal Number (Symbol)</th>\r\n    <th>Ordinal Spelling</th>\r\n  </tr>\r\n  <tr>\r\n    <td>1</td>\r\n    <td>One</td>\r\n    <td>1st</td>\r\n    <td>First</td>\r\n  </tr>\r\n  <tr>\r\n    <td>2</td>\r\n    <td>Two</td>\r\n    <td>2nd</td>\r\n    <td>Second</td>\r\n  </tr>\r\n  <tr>\r\n    <td>3</td>\r\n    <td>Three</td>\r\n    <td>3rd</td>\r\n    <td>Third</td>\r\n  </tr>\r\n  <tr>\r\n    <td>4</td>\r\n    <td>Four</td>\r\n    <td>4th</td>\r\n    <td>Fourth</td>\r\n  </tr>\r\n  <tr>\r\n    <td>5</td>\r\n    <td>Five</td>\r\n    <td>5th</td>\r\n    <td>Fifth (bukan <i>fiveth</i>)</td>\r\n  </tr>\r\n  <tr>\r\n    <td>8</td>\r\n    <td>Eight</td>\r\n    <td>8th</td>\r\n    <td>Eighth (cukup tambah -h)</td>\r\n  </tr>\r\n  <tr>\r\n    <td>9</td>\r\n    <td>Nine</td>\r\n    <td>9th</td>\r\n    <td>Ninth (huruf \'e\' lebur)</td>\r\n  </tr>\r\n  <tr>\r\n    <td>11</td>\r\n    <td>Eleven</td>\r\n    <td>11th</td>\r\n    <td>Eleventh</td>\r\n  </tr>\r\n  <tr>\r\n    <td>12</td>\r\n    <td>Twelve</td>\r\n    <td>12th</td>\r\n    <td>Twelfth (huruf \'ve\' berubah ke \'f\')</td>\r\n  </tr>\r\n  <tr>\r\n    <td>13</td>\r\n    <td>Thirteen</td>\r\n    <td>13th</td>\r\n    <td>Thirteenth</td>\r\n  </tr>\r\n  <tr>\r\n    <td>20</td>\r\n    <td>Twenty</td>\r\n    <td>20th</td>\r\n    <td>Twentieth (huruf \'y\' menjadi \'ie\')</td>\r\n  </tr>\r\n  <tr>\r\n    <td>21</td>\r\n    <td>Twenty-one</td>\r\n    <td>21st</td>\r\n    <td>Twenty-first</td>\r\n  </tr>\r\n  <tr>\r\n    <td>22</td>\r\n    <td>Twenty-two</td>\r\n    <td>22nd</td>\r\n    <td>Twenty-second</td>\r\n  </tr>\r\n  <tr>\r\n    <td>23</td>\r\n    <td>Twenty-three</td>\r\n    <td>23rd</td>\r\n    <td>Twenty-third</td>\r\n  </tr>\r\n  <tr>\r\n    <td>30</td>\r\n    <td>Thirty</td>\r\n    <td>30th</td>\r\n    <td>Thirtieth</td>\r\n  </tr>\r\n  <tr>\r\n    <td>31</td>\r\n    <td>Thirty-one</td>\r\n    <td>31st</td>\r\n    <td>Thirty-first</td>\r\n  </tr>\r\n</table>\r\n\r\n<h3>5. Penggunaan Khusus dalam Konteks Kalimat</h3>\r\n\r\n<p><b>A. Menyebutkan Tanggal (Dates):</b></p>\r\n<ul>\r\n  <li>Format penulisan: <i>17 August</i> atau <i>August 17th</i>.</li>\r\n  <li>Cara pengucapan lisan: selalu ucapkan bentuk ordinalnya: <i>\"the seventeenth of August\"</i> atau <i>\"August the seventeenth\"</i>.</li>\r\n  <li>Preposisi tanggal spesifik adalah <b>\"on\"</b>: <i>\"Indonesia\'s Independence Day is <b>on</b> the seventeenth of August.\"</i></li>\r\n</ul>\r\n\r\n<p><b>B. Menyebutkan Tingkatan Kelas, Lantai, dan Peringkat:</b></p>\r\n<ul>\r\n  <li><i>\"I am in the <b>seventh</b> grade.\"</i> (Saya duduk di kelas 7).</li>\r\n  <li><i>\"The science lab is on the <b>second</b> floor.\"</i> (Lab IPA ada di lantai 2).</li>\r\n  <li><i>\"Bima won the <b>first</b> prize in the speech contest.\"</i> (Bima meraih juara pertama).</li>\r\n</ul>\r\n\r\n<p><b>C. Menyebutkan Nomor Telepon dan Harga:</b></p>\r\n<ul>\r\n  <li>Nomor telepon dibaca satu per satu menggunakan cardinal numbers. Angka 0 biasa dibaca <i>\"zero\"</i> atau <i>\"oh\"</i>. Angka kembar bisa dibaca <i>\"double\"</i>: 0812-77 &rarr; <i>\"oh-eight-one-two, double seven\"</i>.</li>\r\n  <li>Harga: Rp15.000 &rarr; <i>\"fifteen thousand rupiahs\"</i>.</li>\r\n</ul>\r\n\r\n<h3>6. Contoh Percakapan Interaktif (Dialogues in Action)</h3>\r\n\r\n<p><b>Dialogue 1: Asking About Birthday and Date (Menanyakan Hari Ulang Tahun)</b><br>\r\n<i>Situasi: Restu dan Cindy sedang mengisi formulir biodata ekstrakurikuler di kelas.</i></p>\r\n<p>\r\n<b>Restu:</b> \"Cindy, what is your date of birth? The registration form requires it.\"<br>\r\n<b>Cindy:</b> \"I was born on the twenty-second of May, two thousand and thirteen.\"<br>\r\n<b>Restu:</b> \"Let me write that down... May 22nd. So, how old are you now?\"<br>\r\n<b>Cindy:</b> \"I am twelve years old, but I will celebrate my thirteenth birthday next year.\"<br>\r\n<b>Restu:</b> \"Nice! My birthday is on the third of November. We are in the same age group.\"\r\n</p>\r\n\r\n<p><b>Dialogue 2: School Sports Competition (Perlombaan Olahraga Sekolah)</b><br>\r\n<i>Situasi: Arga mengabarkan hasil lomba lari antar-kelas kepada Deni.</i></p>\r\n<p>\r\n<b>Arga:</b> \"Deni, did you watch the 100-meter race during the class meeting?\"<br>\r\n<b>Deni:</b> \"No, I missed it because I had to practice badminton. Who won the competition?\"<br>\r\n<b>Arga:</b> \"Fadli from Class 7A came in first place! He was extremely fast.\"<br>\r\n<b>Deni:</b> \"Awesome! Who took the second and third positions?\"<br>\r\n<b>Arga:</b> \"Reza finished second, and Galang crossed the line in third position. There were eight runners in total.\"<br>\r\n<b>Deni:</b> \"Our class runners did a splendid job!\"\r\n</p>\r\n\r\n<p><b>Dialogue 3: Shopping at the School Canteen (Membeli Makanan & Menghitung Uang)</b><br>\r\n<i>Situasi: Bagas membeli alat tulis di koperasi sekolah.</i></p>\r\n<p>\r\n<b>Bagas:</b> \"Excuse me, Sir. How much are these three notebooks and two blue pens?\"<br>\r\n<b>Shopkeeper:</b> \"Each notebook costs five thousand rupiahs, and the pens are two thousand rupiahs each.\"<br>\r\n<b>Bagas:</b> \"So, three notebooks are fifteen thousand, and two pens are four thousand. That makes nineteen thousand rupiahs in total, right?\"<br>\r\n<b>Shopkeeper:</b> \"That is correct. Here is your receipt, son.\"<br>\r\n<b>Bagas:</b> \"Here is twenty thousand rupiahs, Sir.\"<br>\r\n<b>Shopkeeper:</b> \"Thank you. Here is your change, one thousand rupiahs.\"\r\n</p>\r\n\r\n<h3>7. Catatan Penting & Kesalahan Umum (Common Mistakes)</h3>\r\n<ul>\r\n  <li><b>Kesalahan Ejaan Angka 40 dan 14:</b><br>\r\n  <i>Salah:</i> \"fourty\" (penambahan \'u\' yang keliru pada angka 40).<br>\r\n  <i>Benar:</i> 14 adalah <b>fourteen</b>, tetapi 40 adalah <b>forty</b> (tanpa huruf \'u\').</li>\r\n  <li><b>Kesalahan Ordinal pada Angka 11, 12, dan 13:</b><br>\r\n  <i>Salah:</i> \"11st\" (eleven-first), \"12nd\" (twelve-second), atau \"13rd\" (thirteen-third).<br>\r\n  <i>Benar:</i> 11, 12, dan 13 adalah kelompok belasan, sehingga semuanya berakhiran <b>-th</b>: <b>11th</b> (eleventh), <b>12th</b> (twelfth), dan <b>13th</b> (thirteenth). Aturan -st, -nd, -rd baru berlaku lagi mulai 21st, 22nd, 23rd.</li>\r\n  <li><b>Penulisan Tanggal Tanpa Bentuk Ordinal saat Dibaca Lisan:</b><br>\r\n  <i>Salah membaca:</i> \"My birthday is on October two.\"<br>\r\n  <i>Benar membaca:</i> \"My birthday is on October the <b>second</b>.\"</li>\r\n</ul>\r\n\r\n<h3>8. Kosakata Kunci (Vocabulary Focus)</h3>\r\n<ul>\r\n  <li><b>Cardinal number:</b> Bilangan pokok/cacah (menyatakan jumlah)</li>\r\n  <li><b>Ordinal number:</b> Bilangan bertingkat/urutan (menyatakan posisi/ranking/tanggal)</li>\r\n  <li><b>Quantity:</b> Jumlah / Banyaknya barang</li>\r\n  <li><b>Rank / Standing:</b> Peringkat / Posisi urutan</li>\r\n  <li><b>Digit:</b> Angka / Digit angka</li>\r\n  <li><b>Hyphen:</b> Tanda hubung (-) pada penulisan angka 21 sampai 99</li>\r\n  <li><b>Date of birth:</b> Tanggal lahir</li>\r\n</ul>\r\n\r\n<h3>9. Latihan Soal Pemahaman (Mini Exercises)</h3>\r\n\r\n<p><b>A. Write the following numbers in full English words (Cardinal):</b></p>\r\n<ol>\r\n  <li>48 &rarr; ________________________________________</li>\r\n  <li>115 &rarr; ________________________________________</li>\r\n  <li>250 &rarr; ________________________________________</li>\r\n  <li>1.200 &rarr; ________________________________________</li>\r\n</ol>\r\n\r\n<p><b>B. Write the correct Ordinal symbol and word (e.g., 1 &rarr; 1st / First):</b></p>\r\n<ol>\r\n  <li>3 &rarr; ... / ____________________</li>\r\n  <li>12 &rarr; ... / ____________________</li>\r\n  <li>21 &rarr; ... / ____________________</li>\r\n  <li>30 &rarr; ... / ____________________</li>\r\n</ol>\r\n\r\n<p><b>C. Multiple Choice:</b></p>\r\n<ol>\r\n  <li>Today is the ... of May. We celebrate National Education Day in Indonesia.<br>\r\n      a. two<br>\r\n      b. second<br>\r\n      c. secondary<br>\r\n      d. twice</li>\r\n  <li>There are ... students in Class 7C; eighteen boys and fourteen girls.<br>\r\n      a. thirty-two<br>\r\n      b. thirty-second<br>\r\n      c. twentieth-two<br>\r\n      d. thirteen-two</li>\r\n  <li>My classroom is located on the ... floor of the main building.<br>\r\n      a. three<br>\r\n      b. thirteen<br>\r\n      c. third<br>\r\n      d. thirty</li>\r\n</ol>','2026-09-14 11:56:31',NULL),(7,'Semester 1',1,7,'Introduction to Date','Mempelajari nama hari, nama bulan, dan tata cara penulisan serta pembacaan tanggal dalam bahasa Inggris.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menyebutkan hari, bulan, dan menyatakan tanggal lahir atau momen penting dalam format penulisan resmi bahasa Inggris.</p>\n\n<h3>2. Uraian Materi</h3>\n<p><b>Days of the Week:</b> Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday.<br>\n<b>Months of the Year:</b> January, February, March, April, May, June, July, August, September, October, November, December.</p>\n\n<p><b>Format Tanggal:</b></p>\n<ul>\n  <li>British English: <i>17th August 1945</i> (The seventeenth of August, nineteen forty-five).</li>\n  <li>American English: <i>August 17th, 1945</i> (August the seventeenth, nineteen forty-five).</li>\n</ul>','2026-09-14 11:56:31',NULL),(8,'Semester 1',1,8,'Introduction to Time','Mempelajari cara menanyakan waktu dan membaca jam menggunakan pola O\'clock, Half past, Quarter past, dan Quarter to.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu menanyakan waktu (telling time) dan membaca jam dengan pola standar internasional.</p>\n\n<h3>2. Pola Membaca Jam</h3>\n<ul>\n  <li><b>Tepat:</b> It is ... o\'clock (Contoh: 07.00 = It is seven o\'clock).</li>\n  <li><b>Lewat 15 Menit:</b> A quarter past ... (Contoh: 07.15 = It is a quarter past seven).</li>\n  <li><b>Lewat 30 Menit:</b> A half past ... (Contoh: 07.30 = It is a half past seven).</li>\n  <li><b>Kurang 15 Menit:</b> A quarter to ... (Contoh: 07.45 = It is a quarter to eight).</li>\n</ul>','2026-09-14 11:56:31',NULL),(9,'Semester 1',1,9,'Preposition of Time (In, On, At)','Mempelajari aturan penggunaan kata depan waktu: AT untuk jam spesifik, ON untuk hari dan tanggal, IN untuk bulan, tahun, dan musim.','<h3>1. Aturan Penggunaan Preposition of Time</h3>\n<ul>\n  <li><b>AT (Waktu Spesifik/Jam):</b> at 7 o\'clock, at noon, at night, at midnight.</li>\n  <li><b>ON (Hari & Tanggal Tertentu):</b> on Monday, on Friday, on August 17th, on my birthday.</li>\n  <li><b>IN (Periode Panjang: Bulan, Tahun, Abad):</b> in the morning, in July, in 2026, in summer.</li>\n</ul>\n\n<h3>2. Contoh Kalimat</h3>\n<ul>\n  <li>We go to school <b>at</b> 06:45 AM.</li>\n  <li>We have an English flag ceremony <b>on</b> Monday.</li>\n  <li>SMP Swasta Nommensen was founded <b>in</b> 1985.</li>\n</ul>','2026-09-14 11:56:31',NULL),(10,'Semester 2',2,10,'Vocabularies: Tools, Creatures, and Places','Mempelajari kosakata benda/peralatan sehari-hari (tools), makhluk hidup/hewan (creatures), dan tempat umum (public places).','<h3>1. Pengelompokan Kosakata</h3>\n<ul>\n  <li><b>Tools & Objects:</b> Scissors (Gunting), Hammer (Palu), Broom (Sapu), Ruler (Penggaris).</li>\n  <li><b>Creatures (Makhluk Hidup):</b> Butterfly (Kupu-kupu), Eagle (Elang), Whale (Paus), Rabbit (Kelinci).</li>\n  <li><b>Places (Tempat Umum):</b> Hospital (Rumah Sakit), Library (Perpustakaan), Market (Pasar), School yard (Halaman Sekolah).</li>\n</ul>','2026-09-14 11:56:31',NULL),(11,'Semester 2',2,11,'Introduction to Noun','Mengenal kata benda (Noun), perbedaan Countable Nouns (dapat dihitung) dan Uncountable Nouns (tidak dapat dihitung), serta bentuk jamak (plural).','<h3>1. Klasifikasi Kata Benda (Noun)</h3>\n<ul>\n  <li><b>Countable Noun (Bisa Dihitung):</b> Book -> Books, Pen -> Pens, Student -> Students. Memiliki bentuk singular dan plural (-s/-es).</li>\n  <li><b>Uncountable Noun (Tidak Bisa Dihitung):</b> Water, Sugar, Milk, Rice, Money, Information. Tidak ditambahkan akhiran -s.</li>\n</ul>','2026-09-14 11:56:31',NULL),(12,'Semester 2',2,12,'How Many vs How Much','Mempelajari penggunaan \"How many\" untuk kata benda yang dapat dihitung (countable) dan \"How much\" untuk yang tidak dapat dihitung serta menanyakan harga.','<h3>1. Kaidah Penggunaan How Many & How Much</h3>\n<ul>\n  <li><b>How Many + Plural Countable Noun:</b><br>\n  Contoh: <i>How many pencils do you have?</i> / <i>How many students are in the room?</i></li>\n  <li><b>How Much + Uncountable Noun:</b><br>\n  Contoh: <i>How much water do you drink a day?</i> / <i>How much sugar do we need?</i></li>\n  <li><b>How Much (Menanyakan Harga):</b><br>\n  Contoh: <i>How much is this book? It is Rp 25.000.</i></li>\n</ul>','2026-09-14 11:56:31',NULL),(13,'Semester 2',2,13,'Articles (A, An, The)','Mempelajari kata sandang A, AN (Indefinite Articles) berdasarkan bunyi vokal/konsonan dan THE (Definite Article) untuk benda yang sudah spesifik.','<h3>1. Aturan Penggunaan Articles</h3>\n<ul>\n  <li><b>A:</b> Digunakan sebelum kata benda berbunyi konsonan. (a book, a cat, a university -> bunyi \'yu\').</li>\n  <li><b>AN:</b> Digunakan sebelum kata benda berbunyi vokal (A, I, U, E, O). (an apple, an eraser, an hour -> bunyi \'our\').</li>\n  <li><b>THE:</b> Digunakan untuk benda spesifik yang sudah diketahui oleh pembicara dan pendengar. (The sun, the teacher).</li>\n</ul>','2026-09-14 11:56:31',NULL),(14,'Semester 2',2,14,'Preposition of Place','Mempelajari kata depan penunjuk lokasi/posisi benda seperti in, on, under, beside, between, behind, dan in front of.','<h3>1. Macam-Macam Preposition of Place</h3>\n<ul>\n  <li><b>In:</b> Di dalam (The pen is in the pencil case).</li>\n  <li><b>On:</b> Di atas menempel (The book is on the desk).</li>\n  <li><b>Under:</b> Di bawah (The cat is sleeping under the table).</li>\n  <li><b>Between:</b> Di antara dua benda (The library is between the lab and the canteen).</li>\n  <li><b>Behind:</b> Di belakang (The whiteboard is behind the teacher).</li>\n  <li><b>In front of:</b> Di depan (The teacher stands in front of the class).</li>\n</ul>','2026-09-14 11:56:31',NULL),(15,'Semester 2',2,15,'Aspects of Descriptive Text','Mempelajari struktur teks deskriptif: Identification (pengenalan objek) dan Description (penjelasan ciri fisik/sifat) beserta unsur kebahasaannya.','<h3>1. Tujuan Teks Deskriptif</h3>\n<p>Mendeskripsikan orang, hewan, benda, atau tempat tertentu secara detail dan jelas.</p>\n\n<h3>2. Struktur Generik (Generic Structure)</h3>\n<ul>\n  <li><b>Identification:</b> Bagian pembuka yang mengenalkan objek yang akan dideskripsikan (Who/What).</li>\n  <li><b>Description:</b> Menjelaskan bagian-bagian, ciri fisik, warna, ukuran, sifat, atau perilaku khas objek tersebut.</li>\n</ul>\n\n<h3>3. Ciri Kebahasaan</h3>\n<ul>\n  <li>Menggunakan Simple Present Tense.</li>\n  <li>Banyak menggunakan kata sifat (Adjectives): big, friendly, tall, green.</li>\n</ul>','2026-09-14 11:56:31',NULL),(16,'Semester 2',2,16,'Expression of Asking and Describing','Mempelajari cara menanyakan penampilan fisik/sifat seseorang (\"What does he look like?\") dan memberikan deskripsi yang tepat.','<h3>1. Pertanyaan Menanyakan Ciri & Sifat</h3>\n<ul>\n  <li><b>Penampilan Fisik:</b> \"What does she look like?\" -> She is tall and has long curly hair.</li>\n  <li><b>Sifat / Karakter:</b> \"What is he like?\" -> He is very kind, polite, and humorous.</li>\n  <li><b>Benda:</b> \"What does your bag look like?\" -> It is blue with two zipper pockets.</li>\n</ul>','2026-09-14 11:56:31',NULL),(17,'Semester 2',2,17,'Introduction to Adjective','Mengenal kata sifat (Adjective) yang mendeskripsikan kondisi, ukuran, warna, bentuk, dan perasaan manusia atau karakteristik benda.','<h3>1. Definisi & Kategori Kata Sifat (Adjective)</h3>\n<p>Kata sifat digunakan untuk memberikan keterangan kualitas atau kuantitas pada kata benda (noun).</p>\n<ul>\n  <li><b>Ukuran/Dimensi:</b> Big, Small, Tall, Short, Wide.</li>\n  <li><b>Warna:</b> Red, Blue, White, Black, Yellow.</li>\n  <li><b>Perasaan/Emosi:</b> Happy, Sad, Tired, Excited, Proud.</li>\n  <li><b>Kualitas/Sifat:</b> Diligent, Smart, Friendly, Helpful, Honest.</li>\n</ul>','2026-09-14 11:56:31',NULL),(18,'Semester 2',2,18,'Introduction of Simple Present Tense','Mempelajari pembentukan kalimat Simple Present Tense untuk kebiasaan sehari-hari (habit) dan fakta umum dengan subjek tunggal/jamak.','<h3>1. Rumus Simple Present Tense</h3>\n<ul>\n  <li><b>Kalimat Positif (+):</b><br>\n  - I / You / We / They + V1 (Contoh: They study English every day).<br>\n  - He / She / It + V1 + s/es (Contoh: She studies English every day).</li>\n  <li><b>Kalimat Negatif (-):</b><br>\n  - I / You / We / They + do not + V1.<br>\n  - He / She / It + does not + V1.</li>\n  <li><b>Kalimat Tanya (?):</b><br>\n  - Do/Does + Subject + V1?</li>\n</ul>','2026-09-14 11:56:31',NULL),(19,'Semester 2',2,19,'Contextual Meaning of Songs','Memahami pesan moral, makna kontekstual, dan nilai-nilai inspiratif yang terkandung dalam lirik lagu bahasa Inggris.','<h3>1. Tujuan Pembelajaran</h3>\n<p>Siswa mampu mengidentifikasi fungsi sosial, tema, dan pesan moral (moral message/values) yang disampaikan oleh penulis melalui lirik lagu berbahasa Inggris.</p>\n\n<h3>2. Unsur dalam Lagu</h3>\n<ul>\n  <li><b>Theme (Tema):</b> Friendship (Persahabatan), Love, Motivation, Family, Nature.</li>\n  <li><b>Moral Message:</b> Nasehat atau nilai positif yang dapat dipetik pendengar (Contoh: Never give up on your dreams, appreciate your true friends).</li>\n  <li><b>Rhyme & Rhythm:</b> Rima sajak dan irama nada yang membuat lagu berkesan.</li>\n</ul>','2026-09-14 11:56:31',NULL),(20,'Semester 2',2,20,'Expression of Liking and Dislike','Mempelajari cara menyatakan kesukaan (like/love/enjoy/fond of) dan ketidaksukaan (dislike/hate/don\'t like) terhadap aktivitas atau hobi.','<h3>1. Ungkapan Menyatakan Kesukaan (Expressing Like)</h3>\n<ul>\n  <li>I like / I love playing badminton.</li>\n  <li>I really enjoy reading adventure novels.</li>\n  <li>She is fond of singing English pop songs.</li>\n</ul>\n\n<h3>2. Ungkapan Menyatakan Ketidaksukaan (Expressing Dislike)</h3>\n<ul>\n  <li>I dislike / I don\'t like eating spicy noodles.</li>\n  <li>He hates getting stuck in traffic jams.</li>\n  <li>I can\'t stand noisy environments when studying.</li>\n</ul>','2026-09-14 11:56:31',NULL);
